head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.openTyp = "";         // 여는 방식 R: 접수, H: 이력, N: 신규 (원본 vOpenTyp)
scwin.bzProcsNo = "";       // 업무처리번호 (R: 접수 행, H: 이력 행, N: "") — 신규 저장 성공 뒤 확정 (원본 vBzProcsNo)
scwin.acptNo = "";          // 접수번호 (R 만) (원본 vAcptNo)
scwin.isurCd = "";          // 발행기관코드 (원본 vIsurCd)
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제 (원본 TR_JOB)
scwin.isSaved = false;      // 저장·수정·삭제·신청종목삭제가 한 번이라도 성공했는지 — 닫을 때 부모 재조회 근거
scwin.LIST_BZ_TP_CD = "811";    // 상장업무구분 — PF 변경상장 (원본 VListBzTpCd, LIST_BZ_TP_CD_811)
// 부모 화면(ULDSTF09304)에서 넘겨받는 값 (§1.2)

// 화면 상태값

// 고정값

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
// [신청종목삭제]는 원본 buttonSet 밖의 버튼이라 따로 다룬다(§4).
scwin.BTN_MAP = {
    save : "btn_save",          // [저장]
    modify : "btn_update",      // [수정]
    "delete" : "btn_delete",    // [삭제]
    guide : "btn_dscl"          // [안내문작성]
};

// 원본 : ULDSTF09306.xml (W-Craft 1차 변환 + API 적용 개발 사본, meta_asisFileNm ULDSTF09306.gfm)
/*
 * 화면 동작
 *  - 부모(ULDSTF09304)가 넘긴 여는 방식으로 상세를 채운다.
 *    · 신규(N)·업무처리번호가 없는 접수(R): new 로 종목의 변경전 수량 등 기본값을 받고 상장방식·분배지급기준일을 기본값으로 — [저장]만
 *    · 이력(H)·업무처리번호가 있는 접수(R): select-one-hist 로 그 건을 받는다 — 변경상장일·공시검토 여부로 버튼 상태
 *  - [저장]은 업무처리번호를 채번해 등록, [수정]·[삭제]는 그 건을 고친다. 삭제하면 닫힌다.
 *  - 저장·수정·삭제가 성공하면 닫힐 때 부모가 두 목록을 다시 조회한다(isSaved).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF09306/ULDSTF09306.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09306.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 버튼 잠금 → 파라미터 수신 → 달력 검사 바인딩 → 여는 방식별 상세 조회·버튼 상태. (원본 scwin.init — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 로딩 동안 버튼 잠금 — 조회가 예외로 끝나도 버튼이 XML 기본값(전부 활성)으로 남지 않게 한다.
    $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
    btn_RecvIsuDel.hide();    // 원본도 보이게 하는 곳이 없다(§10 #4)

    // 2) 파라미터 수신 — 원본 getParameter().pData 의 v 접두 키를 평면 camelCase 로(pf 공통 계약서 §2 09306)
    const param = $c.data.getParameter() ?? {};
    scwin.openTyp = String(param.openTyp ?? "");          // AS-IS pData.vOpenTyp
    scwin.bzProcsNo = String(param.bzProcsNo ?? "");      // AS-IS pData.clickBzProcsNo
    scwin.acptNo = String(param.acptNo ?? "");            // AS-IS pData.vAcptNo
    scwin.isurCd = String(param.isurCd ?? "");            // AS-IS pData.vIsurCd
    txb_ISU_CD.setValue(String(param.isuCd ?? ""));       // AS-IS pData.isuCd
    txb_ISU_NM.setValue(String(param.isuNm ?? ""));       // AS-IS pData.isuNm

    // 3) 달력 검사 바인딩(1회) — 단일 달력 checkCalendarFormat(규칙 37)
    $c.date.checkCalendarFormat(edt_LIST_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_BENFCERT_ESTBREPUR_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_TRST_DISTR_PAY_BAS_DD, "yyyyMMdd");

    // 4) 여는 방식별 — 원본은 pData 가 없으면 아무것도 하지 않는다(버튼은 잠긴 채)
    if (scwin.isNewMode()) {
        // 원본은 조회(비동기)를 기다리지 않고 기본값을 넣어, 응답이 늦게 오면 기본값이 덮였다(§8 #3)
        if (!await scwin.selectNew()) return;
        scwin.initNewForm();
        $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
    } else if (scwin.openTyp === "H" || scwin.openTyp === "R") {
        if (!await scwin.selectDetail()) return;
        scwin.applyButtonState();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_save_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09306.btn_save_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_update_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정 버튼 클릭
