/**
 * @method
 * @name scwin.edt_INCDEC_LIST_SHRS_onblur
 * @author Inswave
 * @date 2026. 10. 30
 * @description 증감증권수 포커스 아웃 — 변경후 상장증권수를 다시 계산한다. (원본 edt_INCDEC_LIST_SHRS_OnKillFocus)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.edt_INCDEC_LIST_SHRS_onblur = async function (e) {
    try {
        await scwin.calcListShrs();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09306.edt_INCDEC_LIST_SHRS_onblur" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectNew
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 기본값 조회 — 종목의 변경전 수량 등. (원본 search("N") — §5.1)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectNew = async function () {
    dma_isu.setEmptyValue();

    const sbmOptions = {
        id : "sbm_selectNew",
        method : "get",
        action : "/api/listing/lstproc/pf/chglisting/new",
        target : "dma_isu=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : txb_ISU_CD.getValue() });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    return result.responseJSON?.success === true;    // 실패 안내는 공통 오류 핸들러
};

/**
 * @method
 * @name scwin.selectDetail
 * @author Inswave
 * @date 2026. 10. 30
 * @description 변경상장 이력 상세 조회 — 업무처리번호로. (원본 search() — §5.2)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectDetail = async function () {
    dma_isu.setEmptyValue();

    const sbmOptions = {
        id : "sbm_selectDetail",
        method : "get",
        action : "/api/listing/lstproc/pf/chglisting/select-one-hist",
        target : "dma_isu=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : scwin.bzProcsNo });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    return result.responseJSON?.success === true;    // 실패 안내는 공통 오류 핸들러
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장(insert)·수정(update) 전송 — 성공하면 업무처리번호를 확정하고 다시 조회해 버튼 상태를 맞춘다. (원본 fn_trs — §5.3)
 * @param {String} trJob 처리구분 I: 저장, U: 수정
 * @param {String} bzProcsNo 보낼 업무처리번호 (I: 새로 채번한 번호, U: 지금 건)
 * @returns
 * @hidden N
 */
scwin.saveTrs = async function (trJob, bzProcsNo) {
    const jobNm = (trJob === "I") ? "저장" : "수정";

    const sbmOptions = {
        id : "sbm_saveTrs",
        method : "post",
        action : (trJob === "I") ? "/api/listing/lstproc/pf/chglisting/insert" : "/api/listing/lstproc/pf/chglisting/update",
        ref : "dma_input",
        mediatype : "application/json",
        isProcessMsg : false
    };

    scwin.buildInput(bzProcsNo);
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    // 원본 trs_Save_OnFail → fn_alertMsg('F') 는 서브미션에 연결되지 않아 안내가 없었다(§8 #9)
    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm));
        return;
    }

    scwin.isSaved = true;
    // 성공한 뒤에만 업무처리번호를 확정한다 — 실패한 신규 번호가 남지 않게(§8 #6).
    scwin.bzProcsNo = bzProcsNo;
    await $c.win.alert($c.data.getMessage("com_complete_0096", jobNm));

    // 다시 조회한 뒤 버튼 상태 — 신규 저장은 수정 상태, 그 밖은 변경상장일·공시검토 여부로(원본 search 의 분기).
    // 부모 재조회는 팝업이 닫힌 뒤 부모가 한다(원본 fn_parentRefresh — §8 #8).
    if (!await scwin.selectDetail()) return;
    if (scwin.openTyp === "N") {
        $c.util.setButtonState("grpBtnBox", "update", scwin.BTN_MAP);
    } else {
        scwin.applyButtonState();
    }
};

/**
 * @method
 * @name scwin.removeTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 삭제(delete) 전송 — 성공하면 안내 후 팝업을 닫는다(부모 재조회). (원본 fn_trs(TRS_IDX_DELETE) — §5.4)
 * @returns
 * @hidden N
 */
scwin.removeTrs = async function () {
    const sbmOptions = {
        id : "sbm_removeTrs",
        method : "post",
        action : "/api/listing/lstproc/pf/chglisting/delete",
        ref : "dma_input",
        mediatype : "application/json",
        isProcessMsg : false
    };

    scwin.buildInput(scwin.bzProcsNo);
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
        return;
    }

    scwin.isSaved = true;
    await $c.win.alert($c.data.getMessage("com_complete_0096", "삭제"));
    // 원본은 닫은 뒤에도 다시 조회했다 — 닫고 끝낸다(§8 #7)
    await $c.win.closePopup({ isSaved : true });
};

/**
 * @method
 * @name scwin.removeRecvIsuTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신청종목삭제(delete-isu) 전송 — 새로 채번한 업무처리번호로 보낸다. (원본 fn_RecvtIsuDel 의 전송 — §5.5)
 * @param {String} bzProcsNo 새로 채번한 업무처리번호
 * @returns
 * @hidden N
 */
scwin.removeRecvIsuTrs = async function (bzProcsNo) {
    const sbmOptions = {
        id : "sbm_removeRecvIsu",
        method : "post",
        action : "/api/listing/lstproc/pf/chglisting/delete-isu",
        ref : "dma_input",
        mediatype : "application/json",
        isProcessMsg : false
    };

    scwin.buildInput(bzProcsNo);
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "신청종목삭제"));
        return;
    }

    scwin.isSaved = true;
    await $c.win.alert($c.data.getMessage("com_complete_0096", "삭제"));
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.isNewMode
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 등록으로 여는지 — 신규(N)이거나 업무처리번호가 없는 접수(R). (원본 search 의 insert 상태 조건 — §6.1)
 * @returns {Boolean} 신규 등록이면 true
 * @hidden N
 */
scwin.isNewMode = function () {
    return scwin.openTyp === "N" || (scwin.openTyp === "R" && $c.util.isEmpty(scwin.bzProcsNo));
};

/**
 * @method
 * @name scwin.initNewForm
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 기본값 — 상장방식 변경상장(3), 분배지급기준일 올해 1월 1일. (원본 fn_initItem — §6.2)
 * @returns
 * @hidden N
 */
scwin.initNewForm = function () {
    // 원본의 최초 신규 "X" → 신규상장(4) 분기는 부모가 "X" 를 보내지 않아 쓰이지 않았다(§8 #4)
    dma_isu.set("listMethdTpCd", $c.lc.glb.LIST_METHD_TP_CD_3);
    dma_isu.set("trstDistrPayBasDd", $c.date.getServerDateTime().substring(0, 4) + "0101");
};

/**
 * @method
 * @name scwin.applyButtonState
 * @author Inswave
 * @date 2026. 10. 30
 * @description 기존 건 버튼 상태 — 변경상장일이 오늘 이전이면 조회 상태(error), 공시검토 전(disclsYn ≠ Y)이면 수정 상태(update)로 덮는다.
 * (원본 setButtonSetWithDate + setButtonSetWithDate2 — §6.3)
 * @returns
 * @hidden N
 */
scwin.applyButtonState = function () {
    $c.stf.setButtonSetWithDate(edt_LIST_DD, false, "grpBtnBox", scwin.BTN_MAP);
    // 원본은 그룹·매핑 인자 없이 불러 공시검토 여부가 버튼에 반영되지 않았다(§8 #5)
    $c.stf.setButtonSetWithDate2(dma_isu.get("disclsYn"), "grpBtnBox", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.calcListShrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 변경후 상장증권수 = 변경전 상장증권수 + 증감증권수. 증감증권수가 비면 계산하지 않는다. (원본 fn_calcuate — §6.4)
 * @returns
 * @hidden N
 */
scwin.calcListShrs = async function () {
    const incdec = String(edt_INCDEC_LIST_SHRS.getValue() ?? "");
    if ($c.util.isEmpty(incdec)) return;

    // TODO: 변경사유가 환매(02)여도 더한다(원본과 같음) — 감소분을 빼야 하는지 확인 (§10 #5)
    const sum = Number.parseInt(String(edt_BF_LIST_SHRS.getValue() || 0), 10) + Number.parseInt(incdec, 10);
    if (Number.isNaN(sum)) {
        await $c.win.alert("[증권수 합산처리 중 오류]");
        return;
    }
    dma_isu.set("listShrs", sum);
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장·수정 전 입력 검사 — 걸리면 안내 후 그 칸에 포커스. (원본 fn_CheckForm — §6.5)
 * @returns {Promise<Boolean>} 통과하면 true
 * @hidden N
 */
scwin.validate = async function () {
    const today = $c.date.getServerDateTime().substring(0, 8);
    const listDd = String(edt_LIST_DD.getValue() ?? "");
    const benfDd = String(edt_BENFCERT_ESTBREPUR_DD.getValue() ?? "");
    const payBasDd = String(edt_TRST_DISTR_PAY_BAS_DD.getValue() ?? "");

    if ($c.util.isEmpty(txb_ISU_CD.getValue())) {
        await $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if ($c.util.isEmpty(listDd)) {
        await $c.win.alert("[변경상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (today >= listDd) {
        await $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (!$c.date.isDate(listDd)) {
        await $c.win.alert($c.data.getMessage("com_date_compare_0014"));    // 날짜 형식이 잘못 되었습니다. 확인 후 수정해 주세요.
        edt_LIST_DD.focus();
        return false;
    }
    if ($c.util.isEmpty(benfDd)) {
        await $c.win.alert("[설정및환매일]을 입력하세요.");
        edt_BENFCERT_ESTBREPUR_DD.focus();
        return false;
    }
    if (!$c.date.isDate(benfDd)) {
        await $c.win.alert($c.data.getMessage("com_date_compare_0014"));
        edt_BENFCERT_ESTBREPUR_DD.focus();
        return false;
    }
    if ($c.util.isEmpty(cmb_LIST_METHD_TP_CD.getValue())) {
        await $c.win.alert("[상장방식]을 선택하세요.");
        cmb_LIST_METHD_TP_CD.focus();
        return false;
    }
    if ($c.util.isEmpty(edt_INCDEC_LIST_SHRS.getValue())) {
        // 원본은 이 안내만 await 가 없어 확인을 누르기 전에 다음으로 넘어갔다(§8 #10)
        await $c.win.alert("[증감증권수]을 입력하세요.");
        edt_INCDEC_LIST_SHRS.focus();
        return false;
    }
    if (!await scwin.checkNotZero(edt_INCDEC_LIST_SHRS, "증감증권수")) return false;

    if ($c.util.isEmpty(edt_LIST_SHRS.getValue())) {
        await $c.win.alert("[변경후 상장증권수]을 입력하세요.");
        edt_LIST_SHRS.focus();
        return false;
    }
    if (!await scwin.checkNotZero(edt_LIST_SHRS, "변경후 상장증권수")) return false;

    if ($c.util.isEmpty(cmb_ISU_RSN_CONTN.getValue())) {
        await $c.win.alert("[변경사유]를 입력하세요.");
        cmb_ISU_RSN_CONTN.focus();
        return false;
    }
    if ($c.util.isEmpty(payBasDd)) {
        await $c.win.alert("[분배지급기준일]을 입력하세요.");
        edt_TRST_DISTR_PAY_BAS_DD.focus();
        return false;
    }
    if (!$c.date.isDate(payBasDd)) {
        await $c.win.alert($c.data.getMessage("com_date_compare_0014"));
        edt_TRST_DISTR_PAY_BAS_DD.focus();
        return false;
    }
    if (String(txa_REMK.getValue() ?? "").length > 500) {
        await $c.win.alert("[기타]항목이 입력사이즈를 초과하였습니다.");
        txa_REMK.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.checkNotZero
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수량이 0 이면 안내 후 포커스. (원본 fn_checkNumber — §6.5)
 * @param {Object} comp 수량 입력 컴포넌트
 * @param {String} name 항목명
 * @returns {Promise<Boolean>} 0 이 아니면 true
 * @hidden N
 */
scwin.checkNotZero = async function (comp, name) {
    const val = String(comp.getValue() ?? "");
    if (Number(val) !== 0) return true;

    await $c.win.alert("[" + name + "]를 '" + val + "'으로 입력하셨습니다. 확인 후 재입력바랍니다.");
    comp.focus();
    return false;
};

/**
 * @method
 * @name scwin.getNewBzProcsNo
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 업무처리번호 채번 — pcc 응답 모양(문자열 / { bzProcsNo })을 모두 받는다. (원본 fn_getNewBzProcNo — §6.6)
 * @returns {Promise<String>} 업무처리번호 (실패면 "")
 * @hidden N
 */
scwin.getNewBzProcsNo = async function () {
    // pcc getNewBzProcNo 는 responseJSON 전체를 돌려준다 — 원본은 그 객체를 toString() 해 길이 검사가 늘 실패했다(§8 #6)
    // TODO: 채번 경로가 주식 변경상장(/stock/chglisting/new-bzprocsno)이다 — PF 도 같은 채번인지 확인 (§10 #3)
    const res = await $c.stf.getNewBzProcNo();
    const body = res?.body ?? res;
    return String((typeof body === "object" && body !== null) ? (body.bzProcsNo ?? "") : (body ?? ""));
};

/**
 * @method
 * @name scwin.buildInput
 * @author Inswave
 * @date 2026. 10. 30
 * @description 전송 본문 준비 — 상세(dma_isu)에 접수·업무 키를 더해 dma_input 에 담는다. (원본 fn_trs 앞부분 — §5.3)
 * @param {String} bzProcsNo 보낼 업무처리번호
 * @returns
 * @hidden N
 */
scwin.buildInput = function (bzProcsNo) {
    dma_input.setEmptyValue();
    dma_input.setJSON(dma_isu.getJSON());
    dma_input.set("acptNo", scwin.acptNo);
    dma_input.set("byacptnoSeq", "1");
    dma_input.set("bzProcsNo", bzProcsNo);
    dma_input.set("count", "1");
    dma_input.set("listBzTpCd", scwin.LIST_BZ_TP_CD);
    dma_input.set("isurCd", scwin.isurCd);
    dma_input.set("isuCd", txb_ISU_CD.getValue());
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장 — 검사·확인 뒤 업무처리번호를 채번해 등록한다. (원본 fn_save — §6.7)
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;
    // "[저장] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    const bzProcsNo = await scwin.getNewBzProcsNo();
    if (bzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }
    dma_isu.set("bzProcsNo", bzProcsNo);
    await scwin.saveTrs(scwin.trJob, bzProcsNo);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정 — 검사·확인 뒤 지금 건을 고친다. (원본 fn_update — §6.7)
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;
    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob, scwin.bzProcsNo);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 30
 * @description 삭제 — 확인 뒤 지금 건을 지운다. (원본 fn_delete — §6.7)
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    scwin.trJob = "D";

    // TODO: 원본 주석의 공시 처리상태 검사(fn_check_delete_discls_procsstat)는 대응 API 가 없다 (§10 #6)
    // "[삭제] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.removeTrs();
};

/**
 * @method
 * @name scwin.removeRecvIsu
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신청종목삭제 — 접수 건만. 확인 뒤 업무처리번호를 채번해 신청종목을 지운다. (원본 fn_RecvtIsuDel — §6.8)
 * @returns
 * @hidden N
 */
scwin.removeRecvIsu = async function () {
    if ($c.util.isEmpty(scwin.acptNo)) {
        await $c.win.alert("발행예정내역에서 대상종목을 선택하세요");
        return;
    }

    scwin.trJob = "D";
    if (!await $c.win.confirm($c.stf.getMessageParam("MSG-A006", "신청종목삭제"))) return;

    const bzProcsNo = await scwin.getNewBzProcsNo();
    if (bzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }
    await scwin.removeRecvIsuTrs(bzProcsNo);
};

